self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('universal-calendar-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!ASSETS.some(path=>new URL(path,self.location.href).pathname===url.pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));}return response;}).catch(()=>caches.open(CACHE).then(cache=>cache.match(event.request,{ignoreSearch:true})).then(cached=>cached||Response.error())));});
self.addEventListener('push',event=>{let data={};try{data=event.data?event.data.json():{};}catch{}const title=data.title||'تنبيه التقويم';event.waitUntil(self.registration.showNotification(title,{body:data.body||'التقويم العالمي الشامل',tag:data.tag||title,icon:'./icon.svg',badge:'./icon.svg',data:{url:data.url||'/#worship'}}));});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{const target=event.notification.data&&event.notification.data.url?event.notification.data.url:'./#worship';const url=new URL(target,self.location.href).href;const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});const existing=windows.find(client=>new URL(client.url).origin===self.location.origin);if(existing){await existing.navigate(url);return existing.focus();}return self.clients.openWindow(url);})());});
